import Canvas2D from '../base/Canvas2D';
import random from '../utils/random';
import { mapRange } from '../utils/math';

const palettes = {
  default: ['#BF5E66', '#4C4C59', '#8D93A6', '#F2E394'],
  green: ['#010326', '#022859', '#03A6A6', '#5FD9D9', '#04BFAD'],
  blue: ['#0511F2', '#0540F2', '#527AF2', '#7796F2', '#F2ECD8'],
  dark: ['#0B0C0D', '#1F2326', '#74858C', '#343E40', '#7BA1A6'],
  greyscale: ['#BFBFBF', '#737373', '#262626', '#0D0D0D'],
};

// tweakable params
const PARAMS = {
  palette: 'green',
  size: 40,
  noiseScale: 0.001,
};

// uncomment to create a noise instance
const rand = random();

let test = 0;

export default class Experiment1 extends Canvas2D {
  constructor(options) {
    super(options);

    this.pane.addInput(PARAMS, 'size', { min: 1, max: 100, step: 1 });
    this.pane.addInput(PARAMS, 'noiseScale', {
      min: 0.0,
      max: 0.005,
      step: 0.0001,
    });

    this.pane
      .addInput(PARAMS, 'palette', {
        options: {
          default: 'default',
          green: 'green',
          blue: 'blue',
          dark: 'dark',
          greyscale: 'greyscale',
        },
      })
      .on('change', () => {
        console.log(PARAMS);
      });
    this.pane
      .addButton({
        title: 'Generate',
      })
      .on('click', () => {
        this.drawTriangles();
      });

    this.drawTriangles();
  }

  drawTriangles() {
    this.clear();

    rand.setSeed(Math.random());
    let size = Math.min(this.width, this.height);
    size -= size * 0.1;

    let line,
      dot,
      odd = false,
      lines = [],
      gap = size / PARAMS.size;

    this.ctx.save();

    const posX = this.width / 2 - size * 0.5;
    const posY = this.height / 2 - size * 0.5;

    this.ctx.translate(posX, posY);

    let count = 0;

    for (var y = gap / 2; y <= size; y += gap) {
      odd = !odd;
      line = [];
      for (var x = gap / 4; x <= size; x += gap) {
        dot = { x: x + (odd ? gap / 2 : 0), y: y };
        count++;
        let noiseX = rand.noise2D(x * 0.005, count * 0.004);
        let noiseY = rand.noise2D(x * 0.005, count * 0.004);
        let multiplier = count * PARAMS.noiseScale;
        noiseX *= multiplier;
        noiseY *= multiplier;
        line.push({
          x: x + noiseX * gap + (odd ? gap / 2 : 0),
          y: y + noiseY * gap,
        });
      }
      lines.push(line);
    }

    var dotLine;
    odd = true;

    for (var y = 0; y < lines.length - 1; y++) {
      odd = !odd;
      dotLine = [];
      for (var i = 0; i < lines[y].length; i++) {
        dotLine.push(odd ? lines[y][i] : lines[y + 1][i]);
        dotLine.push(odd ? lines[y + 1][i] : lines[y][i]);
      }
      for (var i = 0; i < dotLine.length - 2; i++) {
        this.drawTriangle(
          dotLine[i],
          dotLine[i + 1],
          dotLine[i + 2],
          this.ctx,
          i
        );
      }
    }

    this.ctx.restore();
  }

  drawTriangle(pointA, pointB, pointC, context, num) {
    context.beginPath();
    context.moveTo(pointA.x, pointA.y);
    context.lineTo(pointB.x, pointB.y);
    context.lineTo(pointC.x, pointC.y);
    context.lineTo(pointA.x, pointA.y);
    context.closePath();

    const noise = rand.noise2D(pointA.x * 0.01, pointA.y * 0.01);
    const alpha = mapRange(noise, -1, 1, 0.5, 1);
    const color = rand.pick(palettes[PARAMS.palette]);

    context.fillStyle = color;
    context.globalAlpha = alpha;
    context.fill();
    // context.stroke();
  }

  onMousePress() {}

  onMouseRelease() {}

  render(dt, time) {}
}
